    function filterBar() {
      const planOptions = planHeadOptions().map(value => `<option value="${htmlEscape(value)}" ${filterState.planHead === value ? "selected" : ""}>${htmlEscape(value)}</option>`).join("");
      const fundSelect = fundOptions.map(value => {
        const label = value === "ALL" ? "All Fund Types" : value === "TOTAL" ? "Overall Total" : value;
        return `<option value="${htmlEscape(value)}" ${filterState.fund === value ? "selected" : ""}>${htmlEscape(label)}</option>`;
      }).join("");
      return `<div class="filterbar">
        <label>Plan Head<select data-filter="planHead"><option value="ALL">All Plan Heads</option>${planOptions}</select></label>
        <label>Fund Type<select data-filter="fund">${fundSelect}</select></label>
        <label>Value Display<select data-display-money><option value="dual" ${displayState.moneyView === "dual" ? "selected" : ""}>Thousands + Cr</option><option value="thousand" ${displayState.moneyView === "thousand" ? "selected" : ""}>Thousands only</option><option value="crore" ${displayState.moneyView === "crore" ? "selected" : ""}>Crores only</option></select></label>
        <button class="reset-btn" type="button" data-reset-filter>Reset Filters</button>
      </div>`;
    }

    function summaryCards(sheet) {
      const view = filteredSheet(sheet);
      const total = view.total.funds[activeFundKey()] || totalFor(view);
      const basis = filterState.fund === "ALL" ? "Overall Total" : filterState.fund;
      return `
        <div class="summary-grid">
          <div class="stat"><div class="label">${htmlEscape(basis)} SBA</div><div class="value">${moneyCell(total.sba)}</div></div>
          <div class="stat"><div class="label">${htmlEscape(basis)} AE</div><div class="value">${moneyCell(total.ae)}</div></div>
          <div class="stat"><div class="label">Available Balance</div><div class="value ${cls(total.available)}">${moneyCell(total.available)}</div></div>
          <div class="stat"><div class="label">Expenditure</div><div class="value">${pct(total.spentPct)}</div></div>
        </div>`;
    }

    function sheetTable(sheet) {
      const view = filteredSheet(sheet);
      const visibleFunds = selectedFundsForTable();
      const groupHeads = visibleFunds.map(f => `<th class="group" colspan="4">${f}</th>`).join("");
      const metricHeads = visibleFunds.map(() => `<th>SBA</th><th>AE</th><th>Available</th><th>Exp %</th>`).join("");
      const rows = view.records.map(rec => planRow(rec, false, visibleFunds)).join("") + planRow(view.total, true, visibleFunds);
      return `
        <div class="table-wrap">
          <table>
            <thead>
              <tr><th rowspan="2">Plan Head</th><th rowspan="2">Plan Head Name</th>${groupHeads}<th class="group" colspan="4">Overall Total</th></tr>
              <tr>${metricHeads}<th>SBA</th><th>AE</th><th>Available</th><th>Exp %</th></tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
        <p class="note">Workbook VAR values are converted here to positive available balance using SBA minus AE.</p>`;
    }

    function planRow(rec, isTotal = false, visibleFunds = funds) {
      if (!rec) return "";
      const cells = visibleFunds.map(f => fundCells(rec.funds[f])).join("");
      const total = rec.funds.TOTAL;
      return `
        <tr class="${isTotal ? "total-row" : ""}">
          <td class="head">${htmlEscape(rec.planHead || "")}</td>
          <td class="name">${htmlEscape(rec.planName || "")}</td>
          ${cells}
          ${fundCells(total)}
        </tr>`;
    }

    function fundCells(values) {
      values = values || emptyFund();
      return `
        <td class="num">${moneyCell(values.sba)}</td>
        <td class="num">${moneyCell(values.ae)}</td>
        <td class="num ${cls(values.available)}">${moneyCell(values.available)}</td>
        <td class="num">${pct(values.spentPct)}</td>`;
    }

    function analysisTable(sheet) {
      const view = filteredSheet(sheet);
      const analysisFunds = filterState.fund === "ALL" ? funds : filterState.fund === "TOTAL" ? ["TOTAL"] : [filterState.fund];
      const rows = analysisFunds.map(fund => {
        const values = fund === "TOTAL" ? view.total.funds.TOTAL : view.fundAnalysis[fund];
        const width = Math.max(0, Math.min(100, values.spentPct));
        return `
          <tr>
            <td><strong>${fund}</strong></td>
            <td class="num">${moneyCell(values.sba)}</td>
            <td class="num">${moneyCell(values.ae)}</td>
            <td class="num ${cls(values.available)}">${moneyCell(values.available)}</td>
            <td class="num">${pct(values.spentPct)}</td>
            <td class="num">${pct(values.remainPct)}</td>
            <td class="bar-cell"><span>${pct(values.spentPct)}</span><div class="bar"><span style="width:${width}%"></span></div></td>
          </tr>`;
      }).join("");
      return `
        ${summaryCards(view)}
        <div class="table-wrap">
          <table class="analysis-table">
            <thead>
              <tr>
                <th>Fund</th><th>SBA</th><th>AE</th><th>Available</th><th>Expensed %</th><th>Remaining %</th><th>Progress</th>
              </tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>`;
    }

    function reportTable(sheet, reportId) {
      const view = filteredSheet(sheet);
      const rows = view.records.map(rec => reportRow(rec)).join("") + reportRow(view.total, true);
      const fundLabel = filterState.fund === "ALL" ? "Overall Total" : filterState.fund;
      return `
        <div class="toolbar">
          <p class="subtitle">${htmlEscape(sheet.title)} | Fund Type: ${htmlEscape(fundLabel)}</p>
        </div>
        <div class="report-wrap">
          <div class="report-title">Plan Head Expenditure</div>
          <table class="report-table" id="${reportId}">
            <colgroup>
              <col class="col-plan">
              <col class="col-money">
              <col class="col-money">
              <col class="col-var">
              <col class="col-pct">
            </colgroup>
            <thead>
              <tr><th>Plan Head</th><th>SBA 2026-27</th><th>AE</th><th>Variation (3 - 2)</th><th>%age SBA</th></tr>
              <tr class="index-row"><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>`;
    }

    function reportRow(rec, isTotal = false) {
      if (!rec) return "";
      const total = rec.funds[activeFundKey()] || emptyFund();
      const planLabel = rec.planHead || rec.planName || "";
      const variation = total.ae - total.sba;
      return `
        <tr class="${isTotal ? "total-row" : ""}">
          <td>${htmlEscape(planLabel)}</td>
          <td class="num">${moneyCell(total.sba)}</td>
          <td class="num">${moneyCell(total.ae)}</td>
          <td class="num">${moneyCell(variation)}</td>
          <td class="num">${total.sba ? total.spentPct.toFixed(2) : "#DIV/0!"}</td>
        </tr>`;
    }

    function reportTableForExport(sheet) {
      const rows = sheet.records.map(rec => reportRow(rec)).join("") + reportRow(sheet.total, true);
      return `
        <h2>${htmlEscape(sheet.sheetName)} - Plan Head Expenditure</h2>
        <table border="1">
          <thead>
            <tr><th>Plan Head</th><th>SBA 2026-27</th><th>AE</th><th>Variation (3 - 2)</th><th>%age SBA</th></tr>
            <tr><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>`;
    }

    function fundAnalysisForExport(sheet) {
      const rows = funds.map(fund => {
        const values = sheet.fundAnalysis[fund];
        return `
          <tr>
            <td>${fund}</td>
            <td class="num">${moneyCell(values.sba)}</td>
            <td class="num">${moneyCell(values.ae)}</td>
            <td class="num ${cls(values.available)}">${moneyCell(values.available)}</td>
            <td>${pct(values.spentPct)}</td>
            <td>${pct(values.remainPct)}</td>
          </tr>`;
      }).join("");
      return `
        <h2>${htmlEscape(sheet.sheetName)} - Fund Analysis</h2>
        <table border="1">
          <thead>
            <tr><th>Fund</th><th>SBA</th><th>AE</th><th>Available</th><th>Expensed %</th><th>Remaining %</th></tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>`;
    }

    function frExportStyles(mode = "excel") {
      return `
        @page { size: A4 landscape; margin: .25in; }
        :root { --text:#1f2933; --muted:#607080; --line:#d8e0e8; --good:#126a3a; --bad:#a13131; --accent:#126a66; }
        * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
        body { margin:0; background:#ffffff; color:var(--text); font-family: Arial, Helvetica, sans-serif; font-size:10px; }
        main { width:100%; margin:0 auto; }
        h1 { margin:0 0 4px; text-align:center; color:#1f4e79; font-size:20px; }
        h2 { margin:8px 0 5px; color:#1f4e79; font-size:14px; text-transform:uppercase; }
        .export-meta { margin:0 0 7px; text-align:right; color:var(--muted); font-weight:700; }
        .export-section { page-break-after:always; break-after:page; padding-top:2mm; }
        .export-section:last-child { page-break-after:auto; break-after:auto; }
        .filterbar, .toolbar .subtitle { display:none; }
        .summary-grid { display:grid; grid-template-columns:repeat(4, 1fr); gap:6px; margin:0 0 7px; }
        .stat { border:1px solid var(--line); background:#f8fbfd; padding:6px; border-radius:4px; }
        .stat .label { color:var(--muted); font-size:10px; text-transform:uppercase; font-weight:700; }
        .stat .value { margin-top:4px; font-size:14px; font-weight:700; }
        .table-wrap, .report-wrap { overflow:visible; border:1px solid var(--line); background:#ffffff; padding:0; }
        table { border-collapse:collapse; width:100%; table-layout:fixed; font-size:8.2px; }
        th, td { border:1px solid #000000; padding:2px 3px; vertical-align:middle; white-space:normal; word-break:break-word; overflow-wrap:anywhere; }
        th { background:#1f4e79; color:#ffffff; text-align:center; font-weight:700; }
        th.group { background:#d9e7e4; color:#123f3c; }
        td { background:#f8fbfd; }
        tbody tr:nth-child(even) td { background:#e8f2f8; }
        tr.total-row td { background:#c8d6e8; font-weight:700; }
        td.num { text-align:right; font-variant-numeric:tabular-nums; }
        td.name { width:13%; }
        td.head { text-align:center; font-weight:700; }
        .positive { color:var(--good); }
        .negative { color:var(--bad); }
        .report-title { margin:0 0 4px; color:#1f4e79; font-weight:700; text-transform:uppercase; }
        .report-figure, .note { color:var(--muted); font-size:10px; font-weight:700; text-align:right; }
        .bar { height:7px; background:#edf1f5; border-radius:99px; overflow:hidden; }
        .bar > span { display:block; height:100%; background:var(--accent); }
        .dual-money { display:block; text-align:right; line-height:1.08; font-family:"Times New Roman", Times, serif; font-variant-numeric:tabular-nums; }
        .dual-money span { display:block; }
        .dual-money .thousand { font-size:12px; font-weight:700; font-family:"Times New Roman", Times, serif; }
        .dual-money .crore { margin-top:1px; font-size:9.5px; font-family:"Times New Roman", Times, serif; color:#006f78; opacity:1; }
        .dual-money.single .crore { margin-top:0; font-size:12px; opacity:1; }
        .stat .dual-money { text-align:left; }
        .analysis-table, .report-table { font-size:9.5px; }
        ${mode === "excel" ? ".export-section{page-break-after:auto;break-after:auto;margin-bottom:18px}.bar{display:none}" : ""}
      `;
    }

    function frExportDocument(mode = "excel") {
      const generatedAt = new Date().toLocaleString("en-IN");
      const fundLabel = filterState.fund === "ALL" ? "All Fund Types" : filterState.fund === "TOTAL" ? "Overall Total" : filterState.fund;
      const asOn = frDataAsOnText();
      const sections = tabs.map(tab => `<section class="export-section"><h2>${htmlEscape(tab.label)}</h2>${tab.content()}</section>`).join("");
      return `<!doctype html><html><head><meta charset="utf-8"><title>FR Budget Status</title><style>${frExportStyles(mode)}</style></head><body><main><h1>FR Budget Status</h1><p class="export-meta">FR Data as on ${htmlEscape(asOn)} | Generated ${htmlEscape(generatedAt)} | Plan Head: ${htmlEscape(filterState.planHead)} | Fund Type: ${htmlEscape(fundLabel)} | ${htmlEscape(moneyViewLabel())}</p>${sections}</main></body></html>`;
    }

    function xlsxMoney(value) {
      const amount = Number(value || 0);
      if (displayState.moneyView === "thousand") return money(amount);
      if (displayState.moneyView === "crore") return `${croreFmt.format(amount / 10000)} Cr`;
      return `${money(amount)}\n${croreFmt.format(amount / 10000)} Cr`;
    }

    function xlsxSheetName(name) {
      return String(name || "Sheet").replace(/[\\/?*[\]:]/g, " ").replace(/\s+/g, " ").trim().slice(0, 31) || "Sheet";
    }

    function xlsxCell(value, style = "normal", rich = null) {
      return { value: value ?? "", style, rich };
    }

    function xlsxRunColor(style) {
      if (String(style).includes("Good")) return "FF126A3A";
      if (String(style).includes("Bad")) return "FFA13131";
      if (style === "good") return "FF126A3A";
      if (style === "bad") return "FFA13131";
      return "";
    }

    function xlsxMoneyCell(value, style = "normal") {
      const amount = Number(value || 0);
      if (displayState.moneyView === "dual") {
        const main = money(amount);
        const cr = `${croreFmt.format(amount / 10000)} Cr`;
        const color = xlsxRunColor(style);
        return xlsxCell(`${main}\n${cr}`, style, [
          { text: main, size: 11, color },
          { text: "\n" },
          { text: cr, size: 9, color: color || "FF006F78" }
        ]);
      }
      return xlsxCell(xlsxMoney(amount), style);
    }

    function xlsxFinancialStyle(value, total = false, alt = false) {
      if (Number(value || 0) < 0) return total ? "totalBad" : "bad";
      if (Number(value || 0) > 0) return total ? "totalGood" : "good";
      return total ? "total" : alt ? "alt" : "normal";
    }

    function sheetTableRows(sheet) {
      const view = filteredSheet(sheet);
      const visibleFunds = selectedFundsForTable();
      const rows = [
        [xlsxCell(`${sheet.sheetName} - FR Budget Status`, "title")],
        [xlsxCell(sheet.title || "", "meta")],
        [xlsxCell(`FR Data as on ${frDataAsOnText()}`, "meta")],
        [xlsxCell(`Plan Head: ${filterState.planHead} | Fund Type: ${filterState.fund} | ${moneyViewLabel()}`, "meta")],
        [xlsxCell("Plan Head", "header"), xlsxCell("Plan Head Name", "header"), ...visibleFunds.flatMap(fund => [xlsxCell(`${fund} SBA`, "header"), xlsxCell(`${fund} AE`, "header"), xlsxCell(`${fund} Available`, "header"), xlsxCell(`${fund} Exp %`, "header")]), xlsxCell("Overall SBA", "header"), xlsxCell("Overall AE", "header"), xlsxCell("Overall Available", "header"), xlsxCell("Overall Exp %", "header")]
      ];
      [...view.records, view.total].forEach((rec, index) => {
        const isTotal = rec === view.total;
        const alt = index % 2 === 1;
        const row = [xlsxCell(rec.planHead || "", isTotal ? "total" : alt ? "alt" : "normal"), xlsxCell(rec.planName || "", isTotal ? "total" : alt ? "alt" : "normal")];
        visibleFunds.forEach(fund => {
          const values = rec.funds[fund] || emptyFund();
          row.push(xlsxMoneyCell(values.sba, isTotal ? "total" : alt ? "alt" : "normal"));
          row.push(xlsxMoneyCell(values.ae, isTotal ? "total" : alt ? "alt" : "normal"));
          row.push(xlsxMoneyCell(values.available, xlsxFinancialStyle(values.available, isTotal, alt)));
          row.push(xlsxCell(pct(values.spentPct), isTotal ? "total" : alt ? "alt" : "normal"));
        });
        const total = rec.funds.TOTAL || emptyFund();
        row.push(xlsxMoneyCell(total.sba, isTotal ? "total" : alt ? "alt" : "normal"));
        row.push(xlsxMoneyCell(total.ae, isTotal ? "total" : alt ? "alt" : "normal"));
        row.push(xlsxMoneyCell(total.available, xlsxFinancialStyle(total.available, isTotal, alt)));
        row.push(xlsxCell(pct(total.spentPct), isTotal ? "total" : alt ? "alt" : "normal"));
        rows.push(row);
      });
      return rows;
    }

    function reportRows(sheet) {
      const view = filteredSheet(sheet);
      const rows = [
        [xlsxCell(`${sheet.sheetName} - Plan Head Expenditure`, "title")],
        [xlsxCell(sheet.title || "", "meta")],
        [xlsxCell(`FR Data as on ${frDataAsOnText()}`, "meta")],
        [xlsxCell(moneyViewLabel(), "meta")],
        [xlsxCell("Plan Head", "header"), xlsxCell("SBA 2026-27", "header"), xlsxCell("AE", "header"), xlsxCell("Variation (3 - 2)", "header"), xlsxCell("%age SBA", "header")],
        [xlsxCell("1", "subHeader"), xlsxCell("2", "subHeader"), xlsxCell("3", "subHeader"), xlsxCell("4", "subHeader"), xlsxCell("5", "subHeader")]
      ];
      [...view.records, view.total].forEach((rec, index) => {
        const total = rec.funds[activeFundKey()] || emptyFund();
        const isTotal = rec === view.total;
        const alt = index % 2 === 1;
        const variation = total.ae - total.sba;
        rows.push([
          xlsxCell(rec.planHead || rec.planName || "", isTotal ? "total" : alt ? "alt" : "normal"),
          xlsxMoneyCell(total.sba, isTotal ? "total" : alt ? "alt" : "normal"),
          xlsxMoneyCell(total.ae, isTotal ? "total" : alt ? "alt" : "normal"),
          xlsxMoneyCell(variation, xlsxFinancialStyle(variation, isTotal, alt)),
          xlsxCell(total.sba ? total.spentPct.toFixed(2) : "#DIV/0!", isTotal ? "total" : alt ? "alt" : "normal")
        ]);
      });
      return rows;
    }

    function analysisRows(sheet) {
      const view = filteredSheet(sheet);
      const analysisFunds = filterState.fund === "ALL" ? funds : filterState.fund === "TOTAL" ? ["TOTAL"] : [filterState.fund];
      const rows = [
        [xlsxCell(`${sheet.sheetName} - Fund Analysis`, "title")],
        [xlsxCell(sheet.title || "", "meta")],
        [xlsxCell(`FR Data as on ${frDataAsOnText()}`, "meta")],
        [xlsxCell(moneyViewLabel(), "meta")],
        [xlsxCell("Fund", "header"), xlsxCell("SBA", "header"), xlsxCell("AE", "header"), xlsxCell("Available", "header"), xlsxCell("Expensed %", "header"), xlsxCell("Remaining %", "header")]
      ];
      analysisFunds.forEach((fund, index) => {
        const values = fund === "TOTAL" ? view.total.funds.TOTAL : view.fundAnalysis[fund];
        const alt = index % 2 === 1;
        rows.push([
          xlsxCell(fund, alt ? "alt" : "normal"),
          xlsxMoneyCell(values.sba, alt ? "alt" : "normal"),
          xlsxMoneyCell(values.ae, alt ? "alt" : "normal"),
          xlsxMoneyCell(values.available, xlsxFinancialStyle(values.available, false, alt)),
          xlsxCell(pct(values.spentPct), alt ? "alt" : "normal"),
          xlsxCell(pct(values.remainPct), alt ? "alt" : "normal")
        ]);
      });
      return rows;
    }

    function xmlEscape(value) {
      return String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" }[char]));
    }

    function columnName(index) {
      let name = "";
      for (let n = index + 1; n > 0; n = Math.floor((n - 1) / 26)) name = String.fromCharCode(65 + ((n - 1) % 26)) + name;
      return name;
    }

    const styleIndex = { normal: 0, header: 1, subHeader: 2, title: 3, meta: 4, alt: 5, total: 6, good: 7, bad: 8, totalGood: 9, totalBad: 10 };

    function cellWidth(cell) {
      return Math.max(...String(cell?.value ?? "").split("\n").map(part => part.length), 4);
    }

    function worksheetCols(rows) {
      const maxCols = Math.max(1, ...rows.map(row => row.length));
      return Array.from({ length: maxCols }, (_, index) => {
        const maxText = rows.reduce((max, row) => Math.max(max, cellWidth(row[index])), 0);
        const width = Math.max(index < 2 ? 14 : 11, Math.min(index < 2 ? 28 : 18, maxText + 2));
        return `<col min="${index + 1}" max="${index + 1}" width="${width}" customWidth="1"/>`;
      }).join("");
    }

    function richTextXml(cell) {
      if (!cell.rich) return `<is><t xml:space="preserve">${xmlEscape(cell.value)}</t></is>`;
      const runs = cell.rich.map(run => {
        const props = [run.size ? `<sz val="${run.size}"/>` : "", run.color ? `<color rgb="${run.color}"/>` : "", `<rFont val="Times New Roman"/>`].join("");
        return `<r><rPr>${props}</rPr><t xml:space="preserve">${xmlEscape(run.text)}</t></r>`;
      }).join("");
      return `<is>${runs}</is>`;
    }

    function worksheetXml(rows) {
      const cols = worksheetCols(rows);
      const sheetRows = rows.map((row, rIndex) => {
        const cells = row.map((cell, cIndex) => {
          const ref = `${columnName(cIndex)}${rIndex + 1}`;
          const style = styleIndex[cell.style] ?? 0;
          return `<c r="${ref}" t="inlineStr" s="${style}">${richTextXml(cell)}</c>`;
        }).join("");
        const height = rIndex < 4 ? 22 : displayState.moneyView === "dual" ? 30 : 19;
        return `<row r="${rIndex + 1}" ht="${height}" customHeight="1">${cells}</row>`;
      }).join("");
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><cols>${cols}</cols><sheetData>${sheetRows}</sheetData><pageMargins left="0.25" right="0.25" top="0.25" bottom="0.25" header="0.1" footer="0.1"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;
    }

    function stylesXml() {
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="7"><font><sz val="11"/><name val="Times New Roman"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Times New Roman"/></font><font><b/><color rgb="FF1F4E79"/><sz val="14"/><name val="Times New Roman"/></font><font><b/><color rgb="FF607080"/><sz val="10"/><name val="Times New Roman"/></font><font><b/><sz val="11"/><name val="Times New Roman"/></font><font><color rgb="FF126A3A"/><sz val="11"/><name val="Times New Roman"/></font><font><color rgb="FFA13131"/><sz val="11"/><name val="Times New Roman"/></font></fonts><fills count="7"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF1F4E79"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF163B5C"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE8F2F8"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC8D6E8"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF8FBFD"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom style="thin"><color rgb="FF000000"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="11"><xf fontId="0" fillId="6" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf fontId="1" fillId="3" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf fontId="2" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf fontId="3" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="right" vertical="center" wrapText="1"/></xf><xf fontId="0" fillId="4" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="4" fillId="5" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="5" fillId="6" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="6" fillId="6" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="5" fillId="5" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf fontId="6" fillId="5" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
    }

    function crc32(bytes) {
      const table = crc32.table || (crc32.table = Array.from({ length: 256 }, (_, n) => {
        let c = n;
        for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
        return c >>> 0;
      }));
      let crc = -1;
      for (const byte of bytes) crc = (crc >>> 8) ^ table[(crc ^ byte) & 255];
      return (crc ^ -1) >>> 0;
    }

    function zipFiles(files) {
      const encoder = new TextEncoder();
      const chunks = [];
      const central = [];
      let offset = 0;
      const u16 = value => [value & 255, value >>> 8 & 255];
      const u32 = value => [value & 255, value >>> 8 & 255, value >>> 16 & 255, value >>> 24 & 255];
      files.forEach(file => {
        const name = encoder.encode(file.name);
        const data = encoder.encode(file.content);
        const crc = crc32(data);
        const local = new Uint8Array([...u32(0x04034b50), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(name.length), ...u16(0), ...name, ...data]);
        chunks.push(local);
        central.push(new Uint8Array([...u32(0x02014b50), ...u16(20), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(name.length), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(0), ...u32(offset), ...name]));
        offset += local.length;
      });
      const centralSize = central.reduce((sum, part) => sum + part.length, 0);
      const end = new Uint8Array([...u32(0x06054b50), ...u16(0), ...u16(0), ...u16(files.length), ...u16(files.length), ...u32(centralSize), ...u32(offset), ...u16(0)]);
      return new Blob([...chunks, ...central, end], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    }

    function workbookXml(sheetNames) {
      const sheets = sheetNames.map((name, index) => `<sheet name="${xmlEscape(name)}" sheetId="${index + 1}" r:id="rId${index + 1}"/>`).join("");
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets}</sheets></workbook>`;
    }

    function workbookRelsXml(sheetNames) {
      const sheetRels = sheetNames.map((_, index) => `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`).join("");
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheetRels}<Relationship Id="rId${sheetNames.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;
    }

    function contentTypesXml(sheetNames) {
      const sheets = sheetNames.map((_, index) => `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join("");
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets}</Types>`;
    }

    function buildFrWorkbookBlob() {
      const sheets = [
        ...workbookData.map(sheet => ({ name: xlsxSheetName(`${sheet.sheetName} FR`), rows: sheetTableRows(sheet) })),
        ...workbookData.map(sheet => ({ name: xlsxSheetName(`${sheet.sheetName} Report`), rows: reportRows(sheet) })),
        ...workbookData.map(sheet => ({ name: xlsxSheetName(`${sheet.sheetName} Analysis`), rows: analysisRows(sheet) }))
      ];
      const sheetNames = sheets.map(sheet => sheet.name);
      const files = [
        { name: "[Content_Types].xml", content: contentTypesXml(sheetNames) },
        { name: "_rels/.rels", content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>` },
        { name: "xl/workbook.xml", content: workbookXml(sheetNames) },
        { name: "xl/_rels/workbook.xml.rels", content: workbookRelsXml(sheetNames) },
        { name: "xl/styles.xml", content: stylesXml() },
        ...sheets.map((sheet, index) => ({ name: `xl/worksheets/sheet${index + 1}.xml`, content: worksheetXml(sheet.rows) }))
      ];
      return zipFiles(files);
    }

    function exportAllToExcel() {
      const blob = buildFrWorkbookBlob();
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `FR_Budget_Status_${new Date().toISOString().slice(0, 10).replace(/-/g, "")}.xlsx`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(link.href);
    }

    function exportFrPdf() {
      const htmlDoc = frExportDocument("pdf");
      const printWindow = window.open("", "_blank");
      if (!printWindow) {
        window.alert("Popup blocked. Please allow popups for this portal and click Export PDF again.");
        return;
      }
      printWindow.document.open();
      printWindow.document.write(htmlDoc);
      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => printWindow.print(), 350);
    }

    function htmlEscape(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }



    async function requestFrUploadPassword() {
      if (FR_UPLOAD_STATE.unlocked) return true;
      const entered = window.prompt("Enter the local upload password");
      if (!entered || !entered.trim()) return false;
      FR_UPLOAD_STATE.unlocked = true;
      FR_UPLOAD_STATE.password = entered;
      sessionStorage.setItem(FR_UPLOAD_SESSION_KEY, "1");
      return true;
    }
    function formatFileSize(bytes) {
      if (!bytes) return "0 KB";
      if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;
      return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
    }

    function queueFrManifestLoad() {
      if (FR_UPLOAD_STATE.manifest || FR_UPLOAD_STATE.loading) return;
      FR_UPLOAD_STATE.loading = true;
      loadFrUploadManifest().finally(() => {
        FR_UPLOAD_STATE.loading = false;
        if (activeTabId === "fr-upload") renderPanels();
      });
    }

    async function loadFrUploadManifest() {
      const browserManifest = localStorage.getItem(FR_UPLOAD_BROWSER_MANIFEST_KEY);
      try {
        const response = await fetch(`${FR_MANIFEST_URL}?ts=${Date.now()}`);
        const repoManifest = response.ok ? await response.json() : { backups: [] };
        FR_UPLOAD_STATE.manifest = browserManifest ? { ...repoManifest, ...JSON.parse(browserManifest), browserStored: true } : repoManifest;
      } catch (error) {
        FR_UPLOAD_STATE.manifest = browserManifest ? { ...JSON.parse(browserManifest), browserStored: true } : { backups: [], error: error.message };
      }
      return FR_UPLOAD_STATE.manifest;
    }

    function isLocalApiHost() {
      return ["localhost", "127.0.0.1"].includes(window.location.hostname);
    }

    async function validateFrExcelFile(file) {
      if (!file) throw new Error("Please select the latest FR Excel file first.");
      if (!/\.xlsx?$/i.test(file.name)) throw new Error("FR upload accepts only .xls or .xlsx files.");
      const head = new Uint8Array(await file.slice(0, 8).arrayBuffer());
      const isXlsx = head[0] === 0x50 && head[1] === 0x4b;
      const isXls = head[0] === 0xd0 && head[1] === 0xcf && head[2] === 0x11 && head[3] === 0xe0;
      if (!isXlsx && !isXls) throw new Error("Selected file does not look like a valid Excel .xls/.xlsx file.");
      return true;
    }

    function frRoleLabel(role) {
      return role === "previous" ? "Previous FR" : "Current FR";
    }

    function saveFrUploadInBrowser(file, role = "current") {
      const previous = FR_UPLOAD_STATE.manifest || {};
      const asOnDate = selectedFrAsOnDateIso(role);
      const roleManifest = previous[role] || {};
      const previousActive = roleManifest.activeFile || (role === "current" ? previous.activeFile : "");
      const backup = previousActive ? {
        name: `${frRoleLabel(role)} backup - ${new Date().toISOString().slice(0, 10)}`,
        activeFile: previousActive,
        originalName: roleManifest.originalName || (role === "current" ? previous.originalName : "") || previousActive,
        uploadedAt: roleManifest.uploadedAt || (role === "current" ? previous.uploadedAt : "") || asOnDate
      } : null;
      const manifest = {
        ...previous,
        [role]: {
          activeFile: `Browser confirmed: ${file.name}`,
          originalName: file.name,
          uploadedAt: asOnDate,
          backup
        },
        browserStored: true
      };
      if (role === "current") {
        manifest.activeFile = manifest.current.activeFile;
        manifest.originalName = manifest.current.originalName;
        manifest.uploadedAt = manifest.current.uploadedAt;
      }
      localStorage.setItem(FR_UPLOAD_BROWSER_MANIFEST_KEY, JSON.stringify(manifest));
      FR_UPLOAD_STATE.manifest = manifest;
      return manifest;
    }

    function formatUploadDate(value) {
      return value ? new Date(value).toLocaleString("en-IN") : "Not available";
    }

    function selectedFrAsOnDateIso(role = FR_UPLOAD_STATE.view) {
      const date = FR_UPLOAD_STATE.asOnDate[role] || TODAY_ISO;
      return new Date(`${date}T${new Date().toTimeString().slice(0, 8)}`).toISOString();
    }

    function frCopyCard(copy, index, current = false) {
      const title = current ? "Current FR Copy" : `Previous FR Copy ${index + 1}`;
      const fileName = copy?.originalName || copy?.activeFile || copy?.name || "Not available";
      const storedName = copy?.activeFile || copy?.name || "Not available";
      const dataAsOn = formatUploadDate(copy?.dataAsOn || copy?.uploadedAt);
      const storedAt = copy?.uploadedAt && copy?.dataAsOn ? formatUploadDate(copy.uploadedAt) : "";
      return `<div class="fr-copy-card ${current ? "current" : "previous"}"><strong>${title}</strong><span><b>File:</b> ${htmlEscape(fileName)}</span><span><b>Stored as:</b> ${htmlEscape(storedName)}</span><span><b>Data as on:</b> ${htmlEscape(dataAsOn)}</span>${storedAt ? `<span><b>Stored at:</b> ${htmlEscape(storedAt)}</span>` : ""}</div>`;
    }

    function frUploadToggleHtml() {
      return `<div class="copy-view-title">FR Upload Type</div><div class="upload-toggle"><button type="button" class="${FR_UPLOAD_STATE.view === "previous" ? "active" : ""}" data-fr-upload-view="previous">Previous FR - Data As On</button><button type="button" class="${FR_UPLOAD_STATE.view === "current" ? "active" : ""}" data-fr-upload-view="current">Current FR - Data As On</button></div>`;
    }

    function frUploadCopiesHtml(manifest) {
      const role = FR_UPLOAD_STATE.view;
      const roleCopy = manifest[role] || (role === "current" ? { activeFile: manifest.activeFile || "", originalName: manifest.originalName || "", uploadedAt: manifest.uploadedAt || "", dataAsOn: manifest.dataAsOn || "" } : {});
      const copyHtml = roleCopy.activeFile ? frCopyCard(roleCopy, 0, role === "current") : `<div class="fr-copy-card ${role === "current" ? "current" : "previous"}"><strong>${frRoleLabel(role)}</strong><span>No ${frRoleLabel(role).toLowerCase()} file confirmed yet.</span></div>`;
      const backupHtml = roleCopy.backup ? frCopyCard(roleCopy.backup, 0, false) : `<div class="fr-copy-card previous"><strong>${frRoleLabel(role)} Backup Copy</strong><span>No backup copy kept yet. One backup will be kept when this ${frRoleLabel(role).toLowerCase()} is replaced.</span></div>`;
      return `${copyHtml}${backupHtml}`;
    }

    function frUploadPanel() {
      queueFrManifestLoad();
      const manifest = FR_UPLOAD_STATE.manifest || {};
      const activeFile = manifest.activeFile || "No current FR source file confirmed yet";
      const uploadedAt = manifest.dataAsOn || manifest.uploadedAt ? formatUploadDate(manifest.dataAsOn || manifest.uploadedAt) : "Not available";
      const storedAt = manifest.uploadedAt ? formatUploadDate(manifest.uploadedAt) : "Not available";
      const originalName = manifest.originalName || "Not available";
      const backups = (manifest.backups || []).length
        ? manifest.backups.map(copy => `<li><strong>${htmlEscape(copy.name || "Backup Copy")}</strong><br>${htmlEscape((copy.files || []).join(", ") || "Not available")}</li>`).join("")
        : `<li>No backup copy listed yet.</li>`;
      return `
        <div class="upload-card">
          <p class="subtitle">FR browser upload is disabled in the static portal. Use the local GUI sync tool to select the FR workbook, update the repository copy, recalculate this page and refresh Excel/PDF/PPTX exports.</p>
          <div class="upload-status muted">Run from the MB-BUDGET repo folder: <strong>py -3 scripts\\local-sync-gui.py</strong></div>
          <div class="upload-grid">
            <div class="upload-box">
              <h3>Current FR Source</h3>
              <div class="upload-path"><strong>Active file:</strong> ${htmlEscape(activeFile)}</div>
              <div class="upload-path"><strong>Original upload:</strong> ${htmlEscape(originalName)}</div>
              <div class="upload-path"><strong>Data as on:</strong> ${htmlEscape(uploadedAt)}</div>
              <div class="upload-path"><strong>Stored at:</strong> ${htmlEscape(storedAt)}</div>
            </div>
            <div class="upload-box">
              <h3>Last Backup Copies</h3>
              <ol class="backup-list">${backups}</ol>
              <button class="reset-btn" type="button" data-refresh-fr-manifest>Refresh Source List</button>
            </div>
          </div>
          <div class="upload-actions">
            <a class="export-btn upload-btn" href="../scripts/local-sync-gui.py" download>Download/Open GUI Script</a>
            <button class="reset-btn" type="button" data-refresh-fr-manifest>Refresh Source List</button>
          </div>
          <div class="upload-status ${FR_UPLOAD_STATE.statusType}">${htmlEscape(FR_UPLOAD_STATE.status)}</div>
        </div>`;
    }

    async function storeFrUploadFile(role = FR_UPLOAD_STATE.view) {
      if (!await requestFrUploadPassword()) return;
      const file = FR_UPLOAD_STATE.files[role];
      try {
        await validateFrExcelFile(file);
      } catch (error) {
        FR_UPLOAD_STATE.status = error.message;
        FR_UPLOAD_STATE.statusType = "bad";
        renderPanels();
        return;
      }
      const confirmed = window.confirm(`${isLocalApiHost() ? "Store" : "Confirm"} ${file.name} as ${frRoleLabel(role)} with Data as on ${FR_UPLOAD_STATE.asOnDate[role] || TODAY_ISO}? One backup copy will be kept when replaced.`);
      if (!confirmed) {
        FR_UPLOAD_STATE.status = "Upload cancelled. No file was stored.";
        FR_UPLOAD_STATE.statusType = "muted";
        renderPanels();
        return;
      }
      if (!isLocalApiHost() || role === "previous") {
        const saved = saveFrUploadInBrowser(file, role);
        FR_UPLOAD_STATE.files[role] = null;
        FR_UPLOAD_STATE.view = role;
        FR_UPLOAD_STATE.status = `Confirmed browser preview for ${frRoleLabel(role)}: ${saved[role].originalName}. This does not overwrite GitHub repository files; commit/push the file through local workflow for permanent portal update.`;
        FR_UPLOAD_STATE.statusType = "good";
        renderPanels();
        return;
      }
      FR_UPLOAD_STATE.status = "Uploading and storing FR file...";
      FR_UPLOAD_STATE.statusType = "muted";
      renderPanels();
      try {
        const form = new FormData();
        form.append("frFile", file);
        form.append("password", FR_UPLOAD_STATE.password);
        const response = await fetch("../api/fr-upload", { method: "POST", body: form });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok || payload.error) throw new Error(payload.error || "FR upload failed");
        FR_UPLOAD_STATE.files[role] = null;
        FR_UPLOAD_STATE.manifest = payload.saved;
        FR_UPLOAD_STATE.status = `Stored successfully: ${payload.saved.activeFile}`;
        FR_UPLOAD_STATE.statusType = "good";
      } catch (error) {
        const saved = saveFrUploadInBrowser(file, role);
        FR_UPLOAD_STATE.files[role] = null;
        FR_UPLOAD_STATE.view = role;
        FR_UPLOAD_STATE.status = `Local upload API not available, so only browser preview was saved for ${frRoleLabel(role)}: ${saved[role].originalName}. Repository files were not overwritten.`;
        FR_UPLOAD_STATE.statusType = "good";
      }
      renderPanels();
    }
    const tabs = [
      { id: "open-sheet", label: "OPEN LINE FR", content: () => filterBar() + summaryCards(workbookData[0]) + sheetTable(workbookData[0]) },
      { id: "gsu-sheet", label: "GSU FR", content: () => filterBar() + summaryCards(workbookData[1]) + sheetTable(workbookData[1]) },
      { id: "open-report", label: "OPEN LINE Report", content: () => filterBar() + reportTable(workbookData[0], "open-line-report-table") },
      { id: "gsu-report", label: "GSU Report", content: () => filterBar() + reportTable(workbookData[1], "gsu-report-table") },
      { id: "open-analysis", label: "OPEN LINE Analysis", content: () => filterBar() + analysisTable(workbookData[0]) },
      { id: "gsu-analysis", label: "GSU Analysis", content: () => filterBar() + analysisTable(workbookData[1]) },
    ];
    const uploadTab = { id: "fr-upload", label: "Local FR Sync", content: () => frUploadPanel() };
    const panelList = () => [...tabs, uploadTab];

    const tabsEl = document.getElementById("tabs");
    const appEl = document.getElementById("app");

    function renderTabs() {
      tabsEl.innerHTML = tabs.map(tab => `<button class="tab${tab.id === activeTabId ? " active" : ""}" data-tab="${tab.id}">${tab.label}</button>`).join("");
    }

    function renderPanels() {
      appEl.innerHTML = panelList().map(tab => `<section class="panel${tab.id === activeTabId ? " active" : ""}" id="${tab.id}"><h2>${tab.label}</h2>${tab.content()}</section>`).join("");
    }

    function renderAll() {
      renderTabs();
      renderPanels();
    }

    document.getElementById("open-fr-upload").addEventListener("click", async () => {
      if (!await requestFrUploadPassword()) return;
      activeTabId = "fr-upload";
      renderAll();
    });

    tabsEl.addEventListener("click", event => {
      const button = event.target.closest(".tab");
      if (!button) return;
      activeTabId = button.dataset.tab;
      renderAll();
    });

    appEl.addEventListener("change", event => {
      const asOnDateInput = event.target.closest("[data-fr-as-on-date]");
      if (asOnDateInput) {
        const role = asOnDateInput.dataset.frAsOnDate || FR_UPLOAD_STATE.view;
        FR_UPLOAD_STATE.asOnDate[role] = asOnDateInput.value || TODAY_ISO;
        FR_UPLOAD_STATE.status = `${frRoleLabel(role)} data as on date set to ${FR_UPLOAD_STATE.asOnDate[role]}.`;
        FR_UPLOAD_STATE.statusType = "muted";
        renderPanels();
        return;
      }
      const uploadInput = event.target.closest("[data-fr-upload-file]");
      if (uploadInput) {
        const role = uploadInput.dataset.frUploadFile || FR_UPLOAD_STATE.view;
        FR_UPLOAD_STATE.files[role] = uploadInput.files[0] || null;
        FR_UPLOAD_STATE.status = FR_UPLOAD_STATE.files[role] ? `Ready to verify ${frRoleLabel(role)}: ${FR_UPLOAD_STATE.files[role].name}` : `No ${frRoleLabel(role).toLowerCase()} file selected.`;
        FR_UPLOAD_STATE.statusType = FR_UPLOAD_STATE.files[role] ? "good" : "muted";
        renderPanels();
        return;
      }
      const moneyDisplay = event.target.closest("[data-display-money]");
      if (moneyDisplay) {
        displayState.moneyView = moneyDisplay.value || "dual";
        renderPanels();
        return;
      }
      const select = event.target.closest("[data-filter]");
      if (!select) return;
      filterState[select.dataset.filter] = select.value;
      renderPanels();
    });

    appEl.addEventListener("click", event => {
      const uploadViewButton = event.target.closest("[data-fr-upload-view]");
      if (uploadViewButton) {
        FR_UPLOAD_STATE.view = uploadViewButton.dataset.frUploadView;
        renderPanels();
        return;
      }
      if (event.target.closest("[data-reset-filter]")) {
        filterState.planHead = "ALL";
        filterState.fund = "ALL";
        displayState.moneyView = "dual";
        renderPanels();
        return;
      }
      if (event.target.closest("[data-refresh-fr-manifest]")) {
        FR_UPLOAD_STATE.manifest = null;
        FR_UPLOAD_STATE.status = "Refreshing FR source list...";
        FR_UPLOAD_STATE.statusType = "muted";
        loadFrUploadManifest().then(renderPanels);
        return;
      }
      const checkButton = event.target.closest("[data-fr-upload-check]");
      if (checkButton) {
        const role = checkButton.dataset.frUploadCheck || FR_UPLOAD_STATE.view;
        const file = FR_UPLOAD_STATE.files[role];
        if (!file) {
          FR_UPLOAD_STATE.status = `Please select the ${frRoleLabel(role)} Excel file first.`;
          FR_UPLOAD_STATE.statusType = "bad";
          renderPanels();
          return;
        }
        validateFrExcelFile(file)
          .then(() => {
            FR_UPLOAD_STATE.status = `Verified ${frRoleLabel(role)} Excel file: ${file.name} (${formatFileSize(file.size)}), Data as on ${FR_UPLOAD_STATE.asOnDate[role] || TODAY_ISO}.`;
            FR_UPLOAD_STATE.statusType = "good";
            renderPanels();
          })
          .catch(error => {
            FR_UPLOAD_STATE.status = error.message;
            FR_UPLOAD_STATE.statusType = "bad";
            renderPanels();
          });
        return;
      }
      const storeButton = event.target.closest("[data-fr-upload-store]");
      if (storeButton) {
        storeFrUploadFile(storeButton.dataset.frUploadStore || FR_UPLOAD_STATE.view);
      }
    });

    document.getElementById("export-all").addEventListener("click", exportAllToExcel);
    document.getElementById("export-pdf").addEventListener("click", exportFrPdf);

    renderAll();

